# SPDX-License-Identifier: AGPL-3.0-only
import copy

def solve(payload):
    document = copy.deepcopy(payload['document'])
    for operation in payload['operations']:
        path, action = operation['path'], operation['op']
        value = copy.deepcopy(operation.get('value'))
        if path == '':
            document = None if action == 'remove' else value
            continue
        keys = [key.replace('~1', '/').replace('~0', '~') for key in path[1:].split('/')]
        parent = document
        for key in keys[:-1]:
            parent = parent[int(key)] if isinstance(parent, list) else parent[key]
        key = keys[-1]
        if isinstance(parent, list):
            if action == 'remove':
                parent.pop(int(key))
            elif action == 'replace':
                parent[int(key)] = value
            elif key == '-':
                parent.append(value)
            else:
                parent[int(key):int(key) + 1] = [value]
        elif action == 'remove':
            del parent[key]
        else:
            parent[key] = value
    return document

